<x-layout title="Карточка задачи"><div x-data="taskDetail(@js(route('api.tasks.show', $task)))"><div class="page-heading"><div><p class="eyebrow">КАРТОЧКА ЗАДАЧИ</p><h1>{{ \App\Models\Task::TYPES[$task->type] }}</h1><p class="mono muted">{{ $task->id }}</p></div><a class="button secondary" href="{{ route('tasks.index') }}">К списку задач</a></div><p class="poll-status" role="status" x-text="connection"></p><template x-if="task"><div><div class="detail-grid"><section class="panel padded"><div class="panel-heading"><h2>Выполнение</h2><span class="badge" :class="task.status" x-text="statusLabel(task.status)"></span></div><div x-show="task.progress !== null" class="progress-block"><div class="progress-track"><div :style="'width:' + task.progress + '%'"></div></div><strong x-text="task.progress + '%'"></strong></div><p class="notice" x-show="task.status === 'queued'" x-text="delivery?.published_at ? 'RabbitMQ подтвердил публикацию. Ожидание свободного Worker.' : (delivery?.last_error || 'Ожидает публикации диспетчером. Сообщение ещё не подтверждено брокером.')"></p><dl class="details"><dt>Worker</dt><dd class="mono" x-text="task.worker_id || 'Не назначен'"></dd><dt>Попытки в текущем цикле</dt><dd x-text="task.attempts + ' / ' + task.max_attempts"></dd><dt>Создана</dt><dd x-text="date(task.created_at)"></dd><dt>Опубликована</dt><dd x-text="date(task.queued_at)"></dd><dt>Начата</dt><dd x-text="date(task.started_at)"></dd><dt>Завершена</dt><dd x-text="date(task.finished_at)"></dd><dt>Длительность попытки</dt><dd x-text="task.duration_ms === null ? '—' : (task.duration_ms / 1000).toFixed(3) + ' с'"></dd></dl><p class="notice error" x-show="task.error_message" x-text="task.error_message"></p>@can('admin')<form x-show="task.status === 'failed'" method="POST" action="{{ route('tasks.retry', $task) }}">@csrf<button class="button">Повторить задачу</button></form>@endcan</section><section class="panel padded"><h2>Входные данные</h2><pre x-text="JSON.stringify(task.input_data, null, 2)"></pre><h2 class="section-gap">Результат обработки</h2><p class="muted" x-show="!task.result_data">Результат появится после успешного завершения.</p>@include('tasks.result')</section></div><section class="panel section-gap"><div class="panel-heading"><h2>История событий</h2><span class="muted">Последние 100 · время вашего браузера</span></div><div class="event-list"><template x-for="event in task.events" :key="event.id"><div class="event-row"><time x-text="date(event.created_at)"></time><span class="event-kind" x-text="event.event_type"></span><div><p x-text="event.message"></p><small class="mono" x-text="event.worker_id || 'Приложение / диспетчер'"></small></div></div></template></div></section></div></template></div></x-layout>
